style.css:
@-moz-document domain("platform.ididdit.be") {
/* ---------- KLEUREN ---------- */

:root {
    --bg: #0f1017;
    --bg2: #151722;
    --card: #1c1e2a;
    --card-hover: #232638;

    --purple: #7c3aed;
    --purple-light: #9b6cff;
    --purple-dark: #5b21b6;

    --text: #f3f4f6;
    --text-muted: #a9adba;

    --border: #303342;
}


/* ---------- ALGEMEEN ---------- */

html,
body {
    background: var(--bg) !important;
    color: var(--text) !important;
}

body {
    transition: background 0.3s ease, color 0.3s ease !important;
}


/* ---------- BOVENSTE NAVIGATIE ---------- */

header,
nav {
    background: #151620 !important;
    color: var(--text) !important;
    border-bottom: 1px solid var(--border) !important;
    box-shadow: 0 4px 20px rgba(0, 0, 0, .35) !important;
}


/* ---------- TEKST ---------- */

h1,
h2,
h3,
h4,
h5,
h6,
p,
span,
label {
    color: var(--text) !important;
}


/* ---------- LINKS ---------- */

a {
    color: var(--purple-light) !important;
    transition: color .2s ease !important;
}

a:hover {
    color: #b794ff !important;
}


/* ---------- HOOFDBLOK ---------- */

main,
section {
    background: transparent !important;
}


/* ---------- ZOEKVELD ---------- */

input,
textarea,
select {
    background: #1b1d28 !important;
    color: var(--text) !important;
    border: 1px solid #3b3e4e !important;
    border-radius: 10px !important;
}

input::placeholder {
    color: #858999 !important;
}

input:focus,
textarea:focus,
select:focus {
    border-color: var(--purple) !important;
    box-shadow: 0 0 0 3px rgba(124, 58, 237, .2) !important;
    outline: none !important;
}


/* ---------- KNOPPEN ---------- */

button {
    color: white !important;
    background: var(--purple) !important;
    border: none !important;
    border-radius: 9px !important;
    transition:
        background .2s ease,
        transform .15s ease,
        box-shadow .2s ease !important;
}

button:hover {
    background: var(--purple-light) !important;
    box-shadow: 0 0 18px rgba(124, 58, 237, .35) !important;
    transform: translateY(-1px) !important;
}


/* ---------- FILTER KNOPPEN ---------- */

button,
[class*="button"],
[class*="Button"] {
    border-radius: 9px !important;
}


/* ---------- ACTIEVE FILTER ---------- */

[class*="active"],
[class*="selected"] {
    color: white !important;
}


/* ---------- KAARTEN / KLASSEN ---------- */

[class*="card"],
[class*="Card"] {
    background: var(--card) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
    border-radius: 14px !important;

    box-shadow:
        0 8px 25px rgba(0, 0, 0, .25) !important;

    transition:
        transform .2s ease,
        background .2s ease,
        box-shadow .2s ease !important;
}

[class*="card"]:hover,
[class*="Card"]:hover {
    background: var(--card-hover) !important;
    transform: translateY(-3px) !important;

    box-shadow:
        0 12px 30px rgba(0, 0, 0, .4),
        0 0 15px rgba(124, 58, 237, .12) !important;
}


/* ---------- TABS ---------- */

[role="tab"] {
    color: var(--text-muted) !important;
    background: transparent !important;
}

[role="tab"][aria-selected="true"] {
    color: var(--purple-light) !important;
    border-color: var(--purple) !important;
}


/* ---------- HORIZONTALE LIJNEN ---------- */

hr {
    border-color: var(--border) !important;
}


/* ---------- ONDERSTE FOOTER ---------- */

footer {
    background: #101118 !important;
    color: #858999 !important;
    border-top: 1px solid var(--border) !important;
}

footer p,
footer span {
    color: #858999 !important;
}


/* ---------- SCROLLBAR ---------- */

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #0d0e14;
}

::-webkit-scrollbar-thumb {
    background: #3c3650;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--purple);
}


/* ---------- SELECTIE ---------- */

::selection {
    background: var(--purple) !important;
    color: white !important;
}
}
